int irda_sock_recvmsg(struct kiocb *iocb, struct socket *sock,
                      struct msghdr *msg, size_t size, int flags)
{
    struct sock *sk = sock->sk;
    struct sk_buff *skb;
    int copied = 0;
    int err;

    skb = skb_dequeue(&sk->sk_receive_queue);
    if (!skb)
        return -EAGAIN;

    copied = skb->len;
    if (size < copied) {
        msg->msg_flags |= MSG_TRUNC;
        copied = size;
    }

    err = memcpy_to_msg(msg, skb->data, copied);
    if (err) {
        kfree_skb(skb);
        return err;
    }

    kfree_skb(skb);

    if ((sk->sk_shutdown & RCV_SHUTDOWN) &&
        skb_queue_empty(&sk->sk_receive_queue))
        sk->sk_state = IRDA_STATE_CLOSED;

    if (test_bit(IRDA_F_STOPPED, &sk->sk_user_data) &&
        !skb_queue_empty(&sk->sk_receive_queue))
        clear_bit(IRDA_F_STOPPED, &sk->sk_user_data);

    return copied;
}

int irda_recvmsg(struct kiocb *iocb, struct socket *sock, struct msghdr *msg,
                 size_t size, int flags)
{
    struct sock *sk = sock->sk;
    struct sk_buff *skb;
    int len;

    skb = skb_dequeue(&sk->sk_receive_queue);
    if (!skb)
        return -EAGAIN;

    len = skb->len;
    if (size < len) {
        msg->msg_flags |= MSG_TRUNC;
        len = size;
    }

    if (skb_copy_datagram_to_skb(skb, 0, msg->msg_iobuf, 0, len))
        return -EFAULT;

    sock_skb_free(skb);
    if ((sk->sk_shutdown & RCV_SHUTDOWN) && skb_queue_empty(&sk->sk_receive_queue))
        msg->msg_flags |= MSG_EOF;

    if (flags & MSG_WAITALL)
        return len;

    if (sk->sk_flow_stop && !skb_queue_empty(&sk->sk_receive_queue))
        sk->sk_flow_stop = 0;

    return len;
}

int irda_recvmsg(struct kiocb *iocb, struct socket *sock, struct msghdr *msg,
                 size_t size, int flags)
{
    struct sock *sk = sock->sk;
    struct sk_buff *skb;
    int copied = 0;
    int ret = 0;

    skb = skb_dequeue(&sk->sk_receive_queue);
    if (!skb)
        return -EAGAIN;

    copied = min_t(unsigned int, skb->len, size);
    if (copied < skb->len)
        msg->msg_flags |= MSG_TRUNC;

    ret = skb_copy_datagram_msg(skb, 0, msg, copied);
    if (ret)
        goto out;

    if ((sk->sk_shutdown & RCV_SHUTDOWN) && skb_queue_empty(&sk->sk_receive_queue))
        msg->msg_flags |= MSG_EOF;

    /* Check if IrTTP flow is stopped and we have more data in the queue */
    if (sk->sk_state & IRDA_TTP_STOP &&
        !skb_queue_empty(&sk->sk_receive_queue)) {
        sk->sk_state &= ~IRDA_TTP_STOP;
    }

out:
    kfree_skb(skb);
    return copied ? copied : ret;
}

int irda_sock_recvmsg(struct kiocb *iocb, struct socket *sock, struct msghdr *msg,
                      size_t size, int flags)
{
    struct sock *sk = sock->sk;
    int copied = 0;
    int err = 0;
    struct sk_buff *skb;

    skb = skb_dequeue(&sk->sk_receive_queue);
    if (!skb)
        return -EAGAIN;

    copied = min(skb->len, size);
    if (skb->len > copied)
        msg->msg_flags |= MSG_TRUNC;

    err = skb_copy_datagram_msg(skb, 0, msg, copied);
    if (err)
        goto out;

    if ((sk->sk_shutdown & RCV_SHUTDOWN) && skb_queue_empty(&sk->sk_receive_queue))
        msg->msg_flags |= MSG_EOF;

    /* Restart the IrTTP flow if stopped and queue has space */
    if (sk->sk_backlog_rcv && !skb_queue_empty(&sk->sk_receive_queue))
        irtt_start_flow(sk);

out:
    kfree_skb(skb);
    return (err < 0) ? err : copied;
}

int irda_recvmsg(struct kiocb *iocb, struct socket *sock, struct msghdr *msg,
                 size_t size, int flags)
{
    struct sock *sk = sock->sk;
    int noblock = flags & MSG_DONTWAIT;
    int error;
    int copied = 0;

    lock_sock(sk);

    if (sk->sk_receive_queue.next == NULL) {
        if (noblock) {
            release_sock(sk);
            return -EWOULDBLOCK;
        }

        if (signal_pending(current)) {
            release_sock(sk);
            return -ERESTARTSYS;
        }

        skb_queue_wait(&sk->sk_receive_queue);
    }

    struct sk_buff *skb = skb_dequeue(&sk->sk_receive_queue);
    if (!skb) {
        release_sock(sk);
        return -EINVAL;
    }

    if (skb->len > size) {
        msg->msg_flags |= MSG_TRUNC;
        copied = size;
    } else {
        copied = skb->len;
    }

    error = skb_copy_datagram_msg(skb, 0, msg, copied);
    if (error < 0) {
        kfree_skb(skb);
        release_sock(sk);
        return error;
    }

    kfree_skb(skb);

    if (sk->sk_irtt_flow_stopped && skb_queue_len(&sk->sk_receive_queue) < IRDA_FLOW_THRESHOLD)
        irda_resume_flow(sk);

    release_sock(sk);

    return copied;
}
